const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const nyc = ee.Geometry.Point([-74.0060, 40.7128]); // New York City

  // 2. Data Acquisition
  const era5 = ee.ImageCollection('ECMWF/ERA5/DAILY');

  const jan29 = era5
    .filterDate('2019-01-29', '2019-01-30')
    .select('mean_2m_air_temperature');

  const feb5 = era5
    .filterDate('2019-02-05', '2019-02-06')
    .select('mean_2m_air_temperature');

  // Check if collections are empty
  const jan29Count = jan29.size().getInfo();
  const feb5Count = feb5.size().getInfo();

  console.log(`Jan29 Images: ${jan29Count}, Feb5 Images: ${feb5Count}`);

  if (jan29Count === 0 || feb5Count === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get first image from each collection
  const jan29Img = jan29.first();
  const feb5Img = feb5.first();

  // 3. Extract temperature values and convert from Kelvin to Celsius
  const jan29Temp = jan29Img
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: nyc,
      scale: 10000,
      maxPixels: 1e9
    })
    .get('mean_2m_air_temperature')
    .getInfo();

  const feb5Temp = feb5Img
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: nyc,
      scale: 10000,
      maxPixels: 1e9
    })
    .get('mean_2m_air_temperature')
    .getInfo();

  // Convert from Kelvin to Celsius
  const jan29TempC = jan29Temp - 273.15;
  const feb5TempC = feb5Temp - 273.15;
  const tempDiff = Math.abs(jan29TempC - feb5TempC);

  console.log(`Jan29 Temp: ${jan29TempC.toFixed(1)}°C`);
  console.log(`Feb5 Temp: ${feb5TempC.toFixed(1)}°C`);
  console.log(`Difference: ${tempDiff.toFixed(1)}°C`);

  // 4. Validation & Final Answer
  // Check for invalid temperature values (NYC winter range: reasonable -20°C to +20°C)
  if (jan29TempC < -50 || jan29TempC > 50 || feb5TempC < -50 || feb5TempC > 50) {
    console.log("<answer>C3</answer>");
  } else if (tempDiff >= 24) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
